NUMERIC=[]
CACHE={}

def verify(label,a,b):
    assert math.isclose(a,b,rel_tol=1e-8,abs_tol=1e-8),(label,a,b)
    NUMERIC.append(dict(label=label,actual=a,expected=b))

def area(p,n):
    return abs(sum(p[n[i]][0]*p[n[(i+1)%len(n)]][1]-p[n[(i+1)%len(n)]][0]*p[n[i]][1] for i in range(len(n))))/2

def degrees(p,a,o,b):
    u=subv(p[a],p[o]);v=subv(p[b],p[o])
    return math.degrees(math.acos(max(-1,min(1,sum(x*y for x,y in zip(u,v))/math.hypot(*u)/math.hypot(*v)))))

def labels(p):
    return {k:k.replace('1','₁').replace('2','₂') for k in p if not k.startswith('_')}

def add(n,title,statement,answer,rows,p,v,views=None,checks=(),cases=(),**kw):
    B.add(n,'single',statement,answer,rows,p,v,views,checks,cases,collection='theory',title=title,printed=PAGES[n],labels=labels(p),**kw)
    CACHE[n]=deepcopy((rows,p,v,views,checks,cases))

def question(n,statement,answer,rows,p,v,views=None,checks=(),cases=(),**kw):
    B.add(n,'single',statement,answer,rows,p,v,views,checks,cases,collection='selfcheck',title='Вопрос '+str(n),printed=[185 if n<=11 else 186],labels=labels(p),**kw)

def qcopy(n,theory,statement,answer=None):
    source=next(x for x in B.theory if x['number']==theory)
    rows,p,v,views,checks,cases=deepcopy(CACHE[theory])
    question(n,statement,answer or source['answer'],rows,p,v,views,checks,cases,notes=source['notes'])
    # Preserve deliberately authored case-to-step views without sharing objects.
    old=next(x for x in B.models if x['collection']=='theory' and x['number']==theory)
    B.models[-1]['model']=deepcopy(old['model'])

def case_view(v,p,i,step):
    names={k:k+'__case'+str(i) for k in p}
    def ren(x):
        if isinstance(x,str):return names.get(x,x)
        if isinstance(x,list):return [ren(z) for z in x]
        if isinstance(x,dict):return {k:ren(z) for k,z in x.items()}
        return x
    B.models[-1]['model']['views']['step-'+str(step)]={**ren(deepcopy(v)),'label':'Шаг '+str(step)}

def simpair(C=(2,4),k=1.5):
    p=dict(A=[0,0],B=[6,0],C=list(C))
    p.update({z+'1':[9+x/k,y/k] for z,(x,y) in list(p.items())})
    v=sc(['A','B','C','A1','B1','C1'],tri()+tri(['A1','B1','C1']))
    ch=[ratio(a,b,a+'1',b+'1',k) for a,b in tri()]
    for a,o,b in [('B','A','C'),('A','B','C'),('A','C','B')]:
        t=degrees(p,a,o,b);ch += [ang(a,o,b,t),ang(a+'1',o+'1',b+'1',t)]
    return p,v,ch

def marked(v,pairs=3):
    arcs=[]
    for i,(a,o,b) in enumerate([('B','A','C'),('A','B','C'),('A','C','B')][:pairs],1):
        arcs += [arc(o,a,b,i,4),arc(o+'1',a+'1',b+'1',i,4)]
    return more(v,angleArcs=arcs)

