# 67–68. A reflected auxiliary triangle is introduced only by its construction.
def criterion_scene():
    p,v,ch=simpair((2,3),1.5);p['C2']=[2,-3]
    aux=more(v,['C2'],[['A','C2'],['B','C2']])
    ch += [equal(('A','C'),('A','C2')),equal(('B','C'),('B','C2')),ang('B','A','C2',degrees(p,'B','A','C')),ang('A','B','C2',degrees(p,'A','B','C'))]
    return p,v,ch,aux
