# 69. Midline and centroid, including the third median and ratio direction.
def mid_scene(C=(3,5)):
    p=dict(A=[0,0],B=[8,0],C=list(C));p['M']=mid(p['A'],p['C']);p['N']=mid(p['B'],p['C'])
    v=sc('ABCMN',tri()+[['M','N']],equalSegments=[eq('A','M'),eq('M','C'),eq('B','N',2),eq('N','C',2)])
    ch=[col('A','M','C'),col('B','N','C'),equal(('A','M'),('M','C')),equal(('B','N'),('N','C')),par('M','N','A','B'),ratio('M','N','A','B',.5)]
    return p,v,ch
