# 70. Four centers with elementary equidistance arguments (no later chapter assumed).
def orthoscene(C=(2,5)):
    p=dict(A=[0,0],B=[8,0],C=list(C));p['U']=foot(p['A'],p['B'],p['C']);p['V']=foot(p['B'],p['C'],p['A']);p['W']=foot(p['C'],p['A'],p['B']);p['H']=inter(p['A'],p['U'],p['B'],p['V'])
    p['A2']=subv(addv(p['B'],p['C']),p['A']);p['B2']=subv(addv(p['A'],p['C']),p['B']);p['C2']=subv(addv(p['A'],p['B']),p['C'])
    base=sc('ABC',tri());heights=more(base,'UVW',[['A','U'],['B','V'],['C','W']],rightAngles=[rt('A','U','B'),rt('B','V','C'),rt('C','W','B')])
    auxiliary=more(heights,['A2','B2','C2'],tri(['A2','B2','C2']))
    final=more(heights,'H',dashSegments=[['A','H'],['B','H'],['C','H']])
    ch=[perp('A','U','B','C'),perp('B','V','C','A'),perp('C','W','A','B'),col('A','U','H'),col('B','V','H'),col('C','W','H'),par('A2','B2','A','B'),par('B2','C2','B','C'),par('C2','A2','C','A'),equal(('B2','A'),('A','C2'),('B','C')),equal(('C2','B'),('B','A2'),('C','A')),equal(('A2','C'),('C','B2'),('A','B'))]
    return p,base,heights,auxiliary,final,ch
op,ov,oh,oa,of,och=orthoscene()
ip=dict(A=[0,0],B=[8,0],C=[2,6]);lengths=[dist(ip['B'],ip['C']),dist(ip['C'],ip['A']),dist(ip['A'],ip['B'])];ip['I']=[sum(lengths[j]*ip[k][i] for j,k in enumerate('ABC'))/sum(lengths) for i in (0,1)]
for z,a,b in [('K','A','B'),('L','B','C'),('M','C','A')]:ip[z]=foot(ip['I'],ip[a],ip[b])
iv=sc('ABCIKLM',tri()+[['A','I'],['B','I'],['C','I'],['I','K'],['I','L'],['I','M']],rightAngles=[rt('I','K','B'),rt('I','L','C'),rt('I','M','A')],circles=[circle('I','K')])
ich=[equal(('I','K'),('I','L'),('I','M')),perp('I','K','A','B'),perp('I','L','B','C'),perp('I','M','C','A')]
for a,o,b in [('B','A','C'),('C','B','A'),('A','C','B')]:ich += [ang(a,o,'I',degrees(ip,a,o,b)/2),ang('I',o,b,degrees(ip,a,o,b)/2)]
cp=dict(A=[0,0],B=[8,0],C=[2,6],O=[4,2],K=[4,0],L=[5,3],M=[1,3]);cv=sc('ABCOKLM',tri()+[['O','K'],['O','L'],['O','M']],circles=[circle('O','A')],rightAngles=[rt('O','K','B'),rt('O','L','C'),rt('O','M','A')]);cch=[equal(('O','A'),('O','B'),('O','C')),equal(('A','K'),('K','B')),equal(('B','L'),('L','C')),equal(('C','M'),('M','A')),perp('O','K','A','B'),perp('O','L','B','C'),perp('O','M','C','A')]
# Right boundary: the orthocenter coincides with A. Avoid zero-length "heights".
rp=dict(A=[0,0],B=[6,0],C=[0,4],U=foot([0,0],[6,0],[0,4]));rv=sc('ABCU',tri()+[['A','U']],rightAngles=[rt('B','A','C'),rt('A','U','B')]);rch=[perp('A','B','A','C'),perp('A','U','B','C')]
bp,bv,bh,ba,bf,bch=orthoscene((-2,3));bf=more(bf,dashSegments=[['A','H'],['B','H'],['C','H'],['A','W'],['A','V'],['C','U']])
# A final height view uses its own fitting extent; the auxiliary outer triangle
# must not shrink the actual triangle after it has served the proof.
ap={k:v for k,v in op.items() if k not in ('A2','B2','C2')}
bp={k:v for k,v in bp.items() if k not in ('A2','B2','C2')}
bch=bch[:6]

centerrows=[row('Где находится центроид?','Точка пересечения трёх медиан G называется центроидом, центром масс или центром тяжести. Она лежит внутри треугольника и делит каждую медиану в отношении 2 :1, считая от вершины; доказательство дано в пункте 69.','Теорема о медианах.',69),row('Почему биссектрисы имеют общий центр?','Пересечение внутренних биссектрис A и B лежит внутри треугольника. Перпендикуляры из него к сторонам образуют пары прямоугольных треугольников с общей гипотенузой и равными острыми углами; поэтому расстояния до AB, BC и CA равны. Обратно, равные расстояния до сторон угла дают равные прямоугольные треугольники по гипотенузе и катету, значит точка лежит и на биссектрисе C. Это I — центр вписанной окружности: окружность с таким радиусом касается всех трёх сторон.','Признаки равенства прямоугольных треугольников и свойство перпендикуляра как кратчайшего расстояния.',[36,70]),row('Почему серединные перпендикуляры сходятся?','На серединном перпендикуляре к AB точка равноудалена от A и B по равенству прямоугольных треугольников. Обратно, из XA =XB равенство треугольников XKA и XKB при K — середине AB даёт перпендикулярность XK и AB. Если X совпадает с K, он уже лежит на серединном перпендикуляре. Два серединных перпендикуляра к непараллельным сторонам пересекаются в O: OA =OB =OC, поэтому O лежит и на третьем. Окружность с центром O и радиусом OA проходит через все вершины; O — центр описанной окружности.','Равенство треугольников; окружность как множество точек на одном расстоянии от центра.',[15,20,70]),row('Что требуется доказать для высот?','Высоты или содержащие их прямые должны пересекаться в одной точке. Пока проведены только AU, BV и CW, перпендикулярные BC, CA и AB. При тупом угле некоторые основания высот лежат на продолжениях сторон.','Определение высоты; формулировка теоремы.',70),row('Какой вспомогательный треугольник построим?','Через A проведём прямую, параллельную BC; через B — параллельную CA; через C — параллельную AB. Их попарные пересечения образуют △A₂B₂C₂, на сторонах которого лежат A, B, C.','Параллельные прямые; конструкция внешнего треугольника.',[28,70]),row('Почему вершины исходного треугольника стали серединами?','Четырёхугольники, составленные из исходных сторон и построенных параллелей, — параллелограммы. Их противоположные стороны равны: B₂A =AC₂ =BC, C₂B =BA₂ =CA, A₂C =CB₂ =AB. Поэтому A, B, C — середины сторон B₂C₂, C₂A₂, A₂B₂.','Свойства параллелограмма.',48),row('Как получаем общую точку высот?','Прямая AU перпендикулярна BC, значит и параллельной ей B₂C₂; она проходит через середину A. Аналогично BV и CW — серединные перпендикуляры двух других сторон внешнего треугольника. По доказанному свойству они сходятся в одной точке H. Это ортоцентр исходного треугольника.','Сведение высот к серединным перпендикулярам.',70),row('Как меняется положение ортоцентра?','В остроугольном треугольнике две высоты пересекаются внутри. В прямоугольном катеты сами являются высотами, поэтому H совпадает с вершиной прямого угла. В тупоугольном пересекаются продолжения высот, и H находится снаружи. Утверждение о единственной общей точке остаётся верным во всех случаях.','Положение оснований высот и доказанная общая точка.',70)]
add(70,'Четыре замечательные точки треугольника','Центроид, центр вписанной окружности, центр описанной окружности и ортоцентр. Докажите пересечение высот или их продолжений.','Четыре точки — пересечения медиан, внутренних биссектрис, серединных перпендикуляров и прямых высот.',centerrows,op,ov,[ov,ov,ov,oh,oa,oa,of,of],checks=och,cases=[(mp,mv2,'Центроид G',1,mch,labels(mp)),(ip,iv,'Центр вписанной окружности I',2,ich,labels(ip)),(cp,cv,'Центр описанной окружности O',3,cch,labels(cp)),(rp,rv,'Прямой угол: A совпадает с H',8,rch,{'A':'A(H)'}),(bp,bf,'Тупой угол: H вне треугольника',8,bch,labels(bp)),(ap,of,'Острые углы: H внутри треугольника',7,och[:6],labels(ap)),(op,oa,'Вспомогательный треугольник: построение сохранено',6,och,labels(op))],notes=['Пояснения о равноудалённости приведены здесь, чтобы не ссылаться на ещё не разобранную последующую главу об окружности.'])
for s,pp,vv,i in [(1,mp,mv2,1),(2,ip,iv,2),(3,cp,cv,3)]:case_view(vv,pp,i,s)
for s in [7,8]:case_view(of,ap,6,s)

# 71. Hypotenuse projections; explicit correspondence prevents swapped formulas.
def projection_scene(x=3.2,y=4.8):
    p=dict(A=[0,0],B=[x+y,0],C=[x,math.sqrt(x*y)],D=[x,0])
    v=sc('ABC',tri(),rightAngles=[rt('A','C','B')]);h=more(v,'D',[['C','D']],rightAngles=[rt('A','C','B'),rt('C','D','B')])
    ch=[perp('A','C','B','C'),perp('C','D','A','B'),col('A','D','B'),ratio('A','D','D','B',x/y),ratio('C','D','A','D',math.sqrt(y/x)),ratio('D','B','C','D',math.sqrt(y/x)),ratio('A','B','A','C',math.sqrt((x+y)/x)),ratio('A','C','A','D',math.sqrt((x+y)/x)),ratio('A','B','B','C',math.sqrt((x+y)/y)),ratio('B','C','B','D',math.sqrt((x+y)/y))]
    for a,o,b in [('B','A','C'),('A','B','C')]:ch.append(ang(a,o,b,degrees(p,a,o,b)))
    verify('projection height product '+str(x),dist(p['C'],p['D'])**2,dist(p['A'],p['D'])*dist(p['D'],p['B']))
    verify('projection first leg '+str(x),dist(p['A'],p['C'])**2,dist(p['A'],p['B'])*dist(p['A'],p['D']))
    verify('projection second leg '+str(x),dist(p['B'],p['C'])**2,dist(p['A'],p['B'])*dist(p['B'],p['D']))
    return p,v,h,ch
p,v,h,ch=projection_scene();ep,ev,eh,ech=projection_scene(4,4)
altrows=[row('Как провести нужную высоту?','Пусть ∠ACB =90°. Опустим из C перпендикуляр CD на гипотенузу AB. Углы A и B острые, поэтому основание D находится строго между A и B; AD и DB положительны.','Острые углы прямоугольного треугольника; определение высоты.',[31,71]),row('Почему первый малый треугольник подобен большому?','У △ABC и △ACD общий угол A, а углы ACB и ADC прямые. Значит, △ABC ∼△ACD: A ↔A, B ↔C, C ↔D. Особенно важно, что гипотенузе AB соответствует гипотенуза AC.','Первый признак подобия.',66),row('Как записать остальные подобия в правильном порядке?','У △ABC и △CBD общий угол B и прямые углы C и D, поэтому △ABC ∼△CBD: A ↔C, B ↔B, C ↔D. Отсюда △ACD ∼△CBD: A ↔C, C ↔B, D ↔D. Высота делит исходный треугольник на два прямоугольных, подобных ему и друг другу.','Первый признак подобия и соответствие равных углов.',[66,71])]
meanrows=[row('Что значит «среднее пропорциональное»?','Для положительных отрезков длиной x и y средним пропорциональным, или средним геометрическим, называется отрезок длиной z =√(xy). Это равносильно z² =xy и x/z =z/y. Берётся положительный корень, потому что речь о длине.','Определение среднего пропорционального.',71),row('Как выразить высоту?','Из △ACD ∼△CBD получаем AD/CD =CD/DB. Поэтому CD² =AD·DB, то есть CD =√(AD·DB). Высота — среднее пропорциональное между двумя частями гипотенузы.','Подобие малых треугольников.',[64,71]),row('Как выразить каждый катет?','Из △ABC ∼△ACD следует AB/AC =AC/AD, значит AC² =AB·AD. Из △ABC ∼△CBD следует AB/BC =BC/BD, значит BC² =AB·BD. Катет — среднее пропорциональное между всей гипотенузой и его собственной проекцией на неё: для AC берём AD, для BC — BD.','Соответствие сторон в двух подобиях.',[64,71])]
add(71,'Пропорциональные отрезки в прямоугольном треугольнике','Подобие трёх прямоугольных треугольников, среднее пропорциональное и формулы для высоты и катетов через проекции.','△ABC ∼△ACD ∼△CBD; CD² =AD·DB, AC² =AB·AD, BC² =AB·DB.',altrows+meanrows,p,v,[h,h,h,h,h,h],checks=ch,cases=[(ep,eh,'Равные катеты: AD =DB',6,ech+[equal(('A','C'),('B','C')),equal(('A','D'),('D','B'))],labels(ep))])
