p=dict(B=[0,0],C=[2.1,0],A=[2.1,1.7],C1=[6.3,0],A1=[6.3,5.1],U=[-1,-1.3],V=[0,-1.3])
v=sc(['B','C','A','C1','A1','U','V'],[['B','C1'],['A','C'],['A1','C1'],['U','V']],rightAngles=[rt('A','C','B'),rt('A1','C1','B')]);sight=more(v,segs=[['B','A1']])
ch=[col('B','C','C1'),col('B','A','A1'),perp('A','C','B','C1'),perp('A1','C1','B','C1'),ratio('A1','C1','A','C',3),ratio('B','C1','B','C',3)]+[ratio(a,b,'U','V',x) for a,b,x in [('B','C',2.1),('B','C1',6.3),('A','C',1.7),('A1','C1',5.1)]]
# One unit in this separate scene is 10 m on terrain (10 mm on its paper copy).
base=13;ab=base*math.sin(math.radians(58))/math.sin(math.radians(49))
land=dict(A=[0,0],C=[base,0],B=polar([0,0],73,ab),U=[0,-2],V=[1,-2])
lv=sc('ACUV',[['A','C'],['U','V']]);lv1=more(lv,'B',[['A','B'],['C','B']],angleArcs=[arc('A','C','B',1,4),arc('C','A','B',2,4)])
lch=[ang('C','A','B',73),ang('A','C','B',58),ang('A','B','C',49),ratio('A','C','U','V',13),ratio('A','B','U','V',ab)]
# Paper and field are in separate normalized cases; their physical units are stated, not conflated.
