figrows=[row('Как определить подобие любых фигур?','Две фигуры подобны, если можно установить взаимно однозначное соответствие всех их точек так, что расстояние между любой парой соответствующих точек изменяется в одно и то же положительное число k раз. Это определение относится и к многоугольникам, и к криволинейным фигурам.','Общее определение подобия фигур.',64),row('Что означает коэффициент?','Если X ↔X₁ и Y ↔Y₁, то X₁Y₁ =k·XY для любых X и Y. Число k — коэффициент увеличения второй фигуры относительно первой; при обратном сравнении коэффициент 1/k. При k =1 фигуры равны, при k >1 увеличены, при 0 <k <1 уменьшены.','Единый коэффициент для всех расстояний.',[63,64]),row('Почему недостаточно проверить только стороны?','В примере четырёхугольник A₁B₁C₁D₁ получен преобразованием (x,y) ↦(7 +1,5x; 1,5y), поэтому разность координат любой пары точек умножается на 1,5 и её длина тоже. Так проверяются не только стороны, но и диагонали и все другие расстояния. Одни пропорциональные стороны произвольных многоугольников подобия не гарантируют: квадрат и ромб с непрямыми углами могут иметь все стороны равными, но разные углы и диагонали.','Явное преобразование всей фигуры; отличие от третьего признака для треугольников.',[64,68])]
question(14,'Объясните, какие две фигуры называются подобными. Что такое коэффициент подобия фигур?','Соответствие всех точек умножает каждое расстояние на одно положительное число k — коэффициент подобия.',figrows,fp,fv,[fv,fv,fd],checks=fch,notes=['Вопрос относится к произвольным фигурам, а не только к треугольникам; отдельного заголовка теории с этим названием в главе нет.'])

# 74. Acute-angle ratios, independence of size, tangent relation and identity.
def trig_scene(a=4,b=3,k=1.5):
    p=dict(A=[0,0],C=[a,0],B=[a,b]);p.update({z+'1':[a+3+x*k,y*k] for z,(x,y) in list(p.items())})
    p['U']=[0,-2];p['V']=[1,-2]
    v=sc('ABCUV',tri()+[['U','V']],rightAngles=[rt('A','C','B')],angleArcs=[arc('A','C','B',0,6)])
    pair=more(v,['A1','B1','C1'],tri(['A1','B1','C1']),rightAngles=[rt('A','C','B'),rt('A1','C1','B1')],angleArcs=[arc('A','C','B',1,5),arc('A1','C1','B1',1,5)])
    hyp=math.hypot(a,b);ch=[perp('A','C','B','C'),perp('A1','C1','B1','C1'),ang('C','A','B',math.degrees(math.atan2(b,a))),ang('C1','A1','B1',math.degrees(math.atan2(b,a))),ratio('B','C','A','B',b/hyp),ratio('A','C','A','B',a/hyp),ratio('B','C','A','C',b/a)]+[ratio(a0,b0,'U','V',d) for a0,b0,d in [('A','C',a),('B','C',b),('A','B',hyp)]]+[ratio(a0+'1',b0+'1',a0,b0,k) for a0,b0 in tri()]
    return p,v,pair,ch
p,v,tv,ch=trig_scene()
deftrig=[row('Какие стороны относятся к выбранному углу?','Пусть ∠C =90°, ∠A =α, где 0° <α <90°. Сторона AB — гипотенуза, BC — катет, противолежащий углу α, AC — катет, прилежащий к углу α. При выборе угла B роли катетов меняются. На модели UV — одна единица: AC =4, BC =3, AB =5.','Определения катетов относительно выбранного острого угла.',74),row('Как определены три отношения?','Синус острого угла — противолежащий катет, делённый на гипотенузу: sin α =BC/AB. Косинус — прилежащий катет, делённый на гипотенузу: cos α =AC/AB. Тангенс — противолежащий катет, делённый на прилежащий: tg α =BC/AC. Здесь это 3/5, 4/5 и 3/4.','Определения синуса, косинуса и тангенса.',74)]
indtrig=[row('Почему определения не зависят от размера треугольника?','Возьмём два прямоугольных треугольника с ∠A =∠A₁ =α. Прямые углы также равны, поэтому △ABC ∼△A₁B₁C₁. Пусть AB/A₁B₁ =BC/B₁C₁ =AC/A₁C₁ =k.','Первый признак подобия.',66),row('Как сократить общий коэффициент?','Подставим AB =k·A₁B₁, BC =k·B₁C₁, AC =k·A₁C₁. Получим BC/AB =B₁C₁/A₁B₁, AC/AB =A₁C₁/A₁B₁ и BC/AC =B₁C₁/A₁C₁. Значит, синусы, косинусы и тангенсы соответственно равны; каждое отношение зависит от угла, а не от выбранного треугольника.','Сокращение одного и того же положительного множителя.',[63,74])]
tanrow=row('Как связаны тангенс, синус и косинус?','Делим sin α на cos α: (BC/AB)/(AC/AB) =BC/AC =tg α. Деление разрешено, потому что для острого угла AC >0 и cos α >0. Следовательно, tg α =sin α/cos α.','Определения и деление дробей.',74)
idrows=[row('Как вывести основное тригонометрическое тождество?','По определениям sin² α +cos² α =BC²/AB² +AC²/AB² =(BC² +AC²)/AB². В прямоугольном треугольнике по теореме Пифагора BC² +AC² =AB².','Определения и теорема Пифагора.',[60,74]),row('Что получается после сокращения?','Получаем sin² α +cos² α =1. Это основное тригонометрическое тождество. Для острого угла синус и косинус положительны, поэтому, например, cos α =√(1 −sin² α); отрицательный корень длинам сторон не соответствует.','Положительность сторон и доказанное тождество.',74)]
add(74,'Синус, косинус и тангенс острого угла прямоугольного треугольника','Определения трёх отношений, их независимость от размера, tg α =sin α/cos α и sin² α +cos² α =1.','sin α =BC/AB; cos α =AC/AB; tg α =BC/AC =sin α/cos α; sin² α +cos² α =1.',deftrig+indtrig+[tanrow]+idrows,p,v,[v,v,tv,tv,tv,tv,tv],checks=ch)
question(15,'Что называется синусом, косинусом, тангенсом острого угла прямоугольного треугольника?','Это соответственно отношения противолежащего катета к гипотенузе, прилежащего катета к гипотенузе и противолежащего катета к прилежащему.',deftrig+[tanrow],p,v,[v,v,v],checks=ch)
question(16,'Докажите, что равные острые углы двух прямоугольных треугольников имеют равные синусы, косинусы и тангенсы.','По подобию все стороны изменяются в один коэффициент, который сокращается в каждом отношении.',indtrig,p,tv,[tv,tv],checks=ch)
question(17,'Какое равенство называют основным тригонометрическим тождеством?','sin² α +cos² α =1; оно следует из теоремы Пифагора после деления на квадрат гипотенузы.',idrows,p,v,[v,v],checks=ch)
