qcopy(18,75,'Чему равны синус, косинус и тангенс углов 30°, 45° и 60°? Ответ обоснуйте.')
for angle,sine,cosine,tangent in [(30,.5,math.sqrt(3)/2,math.sqrt(3)/3),(45,math.sqrt(2)/2,math.sqrt(2)/2,1),(60,math.sqrt(3)/2,.5,math.sqrt(3))]:
    verify('75 sine '+str(angle),math.sin(math.radians(angle)),sine)
    verify('75 cosine '+str(angle),math.cos(math.radians(angle)),cosine)
    verify('75 tangent '+str(angle),math.tan(math.radians(angle)),tangent)

